import { get, handleApiError, post } from '@helpers/httpClient';

import { mapFrontFundToCreateDto, mapFrontFundToUpdateDto } from '../@mappers/funds.toBack.mapper';
import { mapFundDTOToFront, mapFundWithPaymentsDTOToFront } from '../@mappers/funds.toFront.mapper';
import {
  IFundCreateDTO,
  IFundDTO,
  IFundsListCriteria,
  IFundUpdateDTO,
  IFundWithPaymentsDTO,
} from '../@types/funds.dto.types';
import { IFund, IFundWithPayments } from '../@types/funds.types';

export const getFundsAsync = async (criteria: IFundsListCriteria = {}): Promise<IFund[]> => {
  const res = await get('/ajax/finances/funds_list.php', criteria).then<IFundDTO[]>(handleApiError);
  return res.map(mapFundDTOToFront);
};

export const getOneFundAsync = async (id: number): Promise<IFundWithPayments> => {
  const res = await get('/ajax/finances/fund_one.php', { id }).then<IFundWithPaymentsDTO>(
    handleApiError,
  );
  return mapFundWithPaymentsDTOToFront(res);
};

export const addFundAsync = async (fund: IFund): Promise<IFund> => {
  const data = mapFrontFundToCreateDto(fund);
  const res = await post<{ id: number }, IFundCreateDTO>('/ajax/finances/fund_add.php', data).then(
    handleApiError,
  );
  return {
    ...fund,
    ...res,
  };
};

export const updateFundAsync = async (fund: IFund): Promise<IFund> => {
  const data = mapFrontFundToUpdateDto(fund);
  const res = await post<{ success: boolean }, IFundUpdateDTO>(
    '/ajax/finances/fund_edit.php',
    data,
  ).then(handleApiError);
  if (!res.success) throw new Error('Не удалось обновить');
  return fund;
};

export const deleteFundAsync = async (fund: IFund): Promise<boolean> => {
  const res = await post<{ success: boolean }, { id: number }>('/ajax/finances/fund_edit.php', {
    id: fund.id,
  }).then(handleApiError);
  return res.success;
};
