import { IFundDTO, IFundWithPaymentsDTO } from '../@types/funds.dto.types';
import { IFund, IFundWithPayments } from '../@types/funds.types';
import { mapBackHikingPaymentToFront } from './../../Hiking/@mappers/hikingFinances.mapper';

export const mapFundDTOToFront = (backData: IFundDTO): IFund => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    is_active: backData.is_active === '1',
    is_public: backData.is_public === '1',
    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    archived_at: backData.archived_at ? new Date(backData.archived_at) : null,
    author: {
      id: +backData.id_author,
      name: backData.author_name,
      surname: backData.author_surname,
      photo: backData.author_photo,
    },
  };
};

export const mapFundWithPaymentsDTOToFront = (
  backData: IFundWithPaymentsDTO,
): IFundWithPayments => {
  return {
    ...mapFundDTOToFront(backData),
    payments: backData.payments.map((p) => {
      return {
        ...mapBackHikingPaymentToFront(p),
        hiking: {
          id: +p.id_hiking,
          name: p.hiking_name,
          ava: p.hiking_ava,
          start: new Date(p.hiking_start),
          finish: new Date(p.hiking_finish),
        },
      };
    }),
  };
};
